examples:
.card {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 2px solid;
}

.card {
  position: relative;
  padding: 2rem;
}
.badge {
  position: absolute;
  inset-block-start: 0.5rem;
  inset-inline-end: 0.5rem;
}

nav ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  list-style: none;
  padding: 0;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}
.card {
  flex: 1 1 12rem;
  min-inline-size: 0;
}

.grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  gap: 1rem;
}

:root {
  --surface: #ffffff;
  --ink: #172033;
  --space: 1rem;
}
.card {
  background: var(--surface);
  color: var(--ink);
  padding: var(--space);
}

@layer base, components, utilities;
@layer base {
  p {
    color: #172033;
  }
}
@layer components {
  .note {
    color: #0753a4;
  }
}

@media print {
  nav,
  button {
    display: none;
  }
  body {
    color: black;
    background: white;
  }
}

.cards {
  display: block;
}
@supports (display: grid) {
  .cards {
    display: grid;
    gap: 1rem;
  }
}

.topics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: 1rem;
}

